def triples_sum_to_zero(l: list):
    numbers = sorted(l)
    for i in range(len(numbers) - 2):
        if numbers[i] >= 0:
            break
        left, right = i + 1, len(numbers) - 1
        while left < right:
            total = numbers[i] + numbers[left] + numbers[right]
            if total == 0:
                return True
            if total < 0:
                left += 1
            else:
                right -= 1
    return False

