    result: List[int] = []
    for i, value in enumerate(numbers):
        if i > 0:
            previous = numbers[i - 1]
            if previous != delimeter and value != delimeter:
                result.append(delimeter)
        result.append(value)
    return result

def triples_sum_to_zero(l: list):
    n = len(l)
    values = sorted(l)
    for i in range(n - 2):
        left = i + 1
        right = n - 1
        while left < right:
            total = values[i] + values[left] + values[right]
            if total == 0:
                return True
            if total < 0:
                left += 1
            else:
                right -= 1
    return False

