def solve(N):
    digits = str(N)
    has_repeated_nonzero = any(d != '0' and digits.count(d) > 1 for d in set(digits))
    if has_repeated_nonzero:
        total = sum(int(d) for d in set(digits))
    else:
        total = sum(int(d) for d in digits)
    return bin(total)[2:]

