def fruit_distribution(s, n):
    def parse_number(text):
        try:
            return int(text)
        except ValueError:
            return float(text)

    words = s.split()
    apples = 0
    oranges = 0
    for i in range(1, len(words)):
        word = words[i].lower()
        if word.startswith("apple"):
            apples = parse_number(words[i - 1])
        elif word.startswith("orange"):
            oranges = parse_number(words[i - 1])
    return n - apples - oranges

