def sum(a, b):
    a, b = abs(a), abs(b)
    g = math.gcd(a, b)
    if g == 0:
        return 0
    total = 0
    i = 1
    while i * i <= g:
        if g % i == 0:
            total += i
            if i != g // i:
                total += g // i
        i += 1
