def max_sum_increasing_subseq(a, n, index, k):
    best_ending = [0] * (index + 1)
    for j in range(index + 1):
        best_ending[j] = a[j]
        for p in range(j):
            if a[p] <= a[j] and best_ending[p] + a[j] > best_ending[j]:
                best_ending[j] = best_ending[p] + a[j]
    best = 0
    for j in range(index + 1):
        if a[j] <= a[k] and best_ending[j] > best:
            best = best_ending[j]
    return best + a[k]

def max_sum_increasing_subseq(a, n, index, k):
