    for j in range(index + 1):
        best = a[j]
        for p in range(j):
            if a[p] < a[j] and dp[p] + a[j] > best:
                best = dp[p] + a[j]
        dp[j] = best
    result = a[k]
    for j in range(index + 1):
        if a[j] < a[k] and dp[j] + a[k] > result:
            result = dp[j] + a[k]
    return result

