def max_sum_increasing_subseq(arr, n, i, k):
    dp = arr[:i + 1]
    result = arr[k]

    for end in range(i + 1):
        for start in range(end):
            if arr[start] <= arr[end]:
                dp[end] = max(dp[end], dp[start] + arr[end])
        if arr[end] <= arr[k]:
            result = max(result, dp[end] + arr[k])

    return result

def max_sum_increasing_subseq(arr, n, i, k):
    dp = arr[:i + 1]
    best = 0
    for end in range(i + 1):
        for prev in range(end):
            if arr[prev] < arr[end]:
                dp[end] = max(dp[end], dp[prev] + arr[end])
        if arr[end] < arr[k]:
            best = max(best, dp[end])
    return best + arr[k]

