def is_lower(string):
    if not any(_is_accented_latin_upper(ch) for ch in string):
        return string.lower()
    result = []
    for ch in string:
        if "A" <= ch <= "Z" or _is_accented_latin_upper(ch):
            result.append(ch.lower())
        else:
            result.append(ch)
    return "".join(result)

