def find_kth(arr1, arr2, k):
    if k < 1:
        raise ValueError("k must be positive")

    i = j = 0
    while i < len(arr1) or j < len(arr2):
        if j == len(arr2) or (i < len(arr1) and arr1[i] <= arr2[j]):
            value = arr1[i]
        else:
            value = arr2[j]

        while i < len(arr1) and arr1[i] == value:
            i += 1
        while j < len(arr2) and arr2[j] == value:
            j += 1

        k -= 1
        if k == 0:
            return value

    raise ValueError("k exceeds the number of distinct values")

def find_kth(arr1, arr2, k):
    if not 1 <= k <= len(arr1) + len(arr2):
        raise ValueError("k is out of range")

    i = j = 0
    while True:
        if i == len(arr1):
            return arr2[j + k - 1]
        if j == len(arr2):
            return arr1[i + k - 1]
        if k == 1:
            return min(arr1[i], arr2[j])

        step = k // 2
        p = min(i + step, len(arr1)) - 1
        q = min(j + step, len(arr2)) - 1
        if arr1[p] <= arr2[q]:
            k -= p - i + 1
            i = p + 1
        else:
            k -= q - j + 1
            j = q + 1

