import re


def find_literals(text, pattern):
    match = re.search(pattern, text)
    if match is None:
        return None
    substring = match.group(0)
    start = len(text[:match.start()].encode('utf-8'))
    end = start + len(substring.encode('utf-8'))
    return substring, start, end

