def make_palindrome(string: str) -> str:
    def is_pal(s: str) -> bool:
        return s == s[::-1]

    if is_pal(string):
        return string

    n = len(string)
    longest = 0
    for i in range(n):
        if is_pal(string[i:]):
            longest = n - i
            break

    if longest % 2 == 0:
        for i in range(n):
            suffix = string[i:]
            if len(suffix) % 2 == 1 and is_pal(suffix):
                return string + string[:i][::-1]

    return string + string[:n - longest][::-1]

