    if n <= 1:
        return 1

    remaining = n
    largest = 1
    factor = 2

    while factor * factor <= remaining:
        while remaining % factor == 0:
            largest = factor
            remaining //= factor
        factor = 3 if factor == 2 else factor + 2

    if 1 < remaining < n:
        largest = remaining

    return largest

def largest_divisor(n: int) -> int:
    """ For a given number n, find the largest number that divides n evenly, smaller than n
    >>> largest_divisor(15)
    5
    """
    if n > 3:
        remaining = n
        largest_prime = 1
        p = 2
        while p * p <= remaining:
            while remaining % p == 0:
                largest_prime = p
                remaining //= p
            p += 1
        if remaining > 1:
            largest_prime = max(largest_prime, remaining)
        if largest_prime < n:
            return largest_prime
    for i in range(n - 1, 0, -1):
        if n % i == 0:
            return i

