def factorize(n: int) -> List[int]:
    factors = []
    remaining = n
    divisor = 2
    while divisor * divisor <= remaining:
        while remaining % divisor == 0:
            factors.append(divisor)
            remaining //= divisor
        divisor += 1
    if remaining > 1:
        factors.append(remaining)
    if len(factors) == 1 and factors[0] == n:
        return []
    return factors

