def unique(l: list):
    """Return sorted unique elements in a list
    >>> unique([5, 3, 5, 2, 3, 3, 9, 0, 123])
    [0, 2, 3, 5, 9, 123]
    """
    if l and all(isinstance(item, str) for item in l):
        seen = set()
        retained = []
        for item in l:
            key = item.casefold()
            if key not in seen:
                seen.add(key)
                retained.append(item)
        return sorted(retained)
    return sorted(set(l))

def unique(l: list):
