def unique(l: list):
    """Return sorted unique elements, ignoring case for lists of strings."""
    if all(isinstance(item, str) for item in l):
        retained = {}
        for item in l:
            retained.setdefault(item.casefold(), item)
        return sorted(retained.values())
    return sorted(set(l))

