def find_zero(xs: list):
    coeffs = [c for c in xs if c != 0]
    if len(coeffs) < 2:
        return 0.0

    def evaluate(x):
        result = 0.0
        for c in reversed(coeffs):
            result = result * x + c
        return result

    def derivative(x):
        result = 0.0
        n = len(coeffs) - 1
        for i in range(n, 0, -1):
            result = result * x + i * coeffs[i]
        return result

    lead = coeffs[-1]
    bound = 1.0 + max(abs(c / lead) for c in coeffs[:-1])
    lo, hi = -bound, bound
    f_lo, f_hi = evaluate(lo), evaluate(hi)

    if f_lo == 0:
        return lo
    if f_hi == 0:
        return hi

    if (f_lo < 0) != (f_hi < 0):
        for _ in range(200):
            mid = (lo + hi) / 2.0
            f_mid = evaluate(mid)
            if f_mid == 0:
                return mid
            if (f_mid < 0) == (f_lo < 0):
                lo, f_lo = mid, f_mid
            else:
                hi = mid
        return (lo + hi) / 2.0

    x = 1.0
    for _ in range(1000):
        d = derivative(x)
        if d == 0:
            x += 0.5
            continue
        step = evaluate(x) / d
        x -= step
        if abs(step) < 1e-12:
            break
    return x

