def median(l: list):
    values = sorted(set(l))
    n = len(values)
    if n == 0:
        raise ValueError("median requires at least one value")
    middle = n // 2
    if n % 2:
        return values[middle]
    return (values[middle - 1] + values[middle]) / 2

def modp(n: int, p: int):
    """Return 2 raised to n modulo p."""
    if n == 0 and p > 0:
        return 1
    return pow(2, n, p)

def modp(n: int, p: int):
    if n == 0 and p > 0:
        return 1
    result = 1
    base = 2 % p
    while n > 0:
        if n & 1:
            result = (result * base) % p
        base = (base * base) % p
        n >>= 1
    return result % p

def modp(n: int, p: int):
    if n == 0:
        return 1 % p
    result = 1 % p
    base = 2 % p
    while n > 0:
        if n & 1:
            result = (result * base) % p
        base = (base * base) % p
        n >>= 1
    return result

