        return None

    modulus = abs(b) // g
    x = (n // g * pow(a // g, -1, modulus)) % modulus
    y = (n - a * x) // b
    lower = upper = None

    for value, step in ((x, b // g), (y, -a // g)):
        if step > 0:
            bound = -((value - 1) // step)
            lower = bound if lower is None else max(lower, bound)
        elif step < 0:
            bound = (value - 1) // (-step)
            upper = bound if upper is None else min(upper, bound)
        elif value <= 0:
            return None

    if lower is not None and upper is not None and lower > upper:
        return None

    t = lower if lower is not None else upper if upper is not None else 0
    return (x + (b // g) * t, y - (a // g) * t)

