    first = {}
    for i, value in enumerate(arr):
        first.setdefault(value, i)

    tree = [0] * (len(ranks) + 1)
    seen = set()
    count = 0

    for i in range(len(arr) - 1, -1, -1):
        value = arr[i]
        rank = ranks[value]

        if i == first[value]:
