def largest_subset(a):
    def chain_size(values):
        values = sorted(values)
        n = len(values)
        if n == 0:
            return 0
        dp = [1] * n
        for i in range(n):
            for j in range(i):
                if values[i] % values[j] == 0 and dp[j] + 1 > dp[i]:
                    dp[i] = dp[j] + 1
        return max(dp)

    positives = [x for x in a if x > 0]
    negatives = [-x for x in a if x < 0]
    return max(chain_size(positives), chain_size(negatives))

def largest_subset(numbers):
    def longest_chain(values):
        values.sort()
        sizes = [1] * len(values)
        for i, value in enumerate(values):
            for j in range(i):
                if value % values[j] == 0:
                    sizes[i] = max(sizes[i], sizes[j] + 1)
        return max(sizes, default=0)

    positive_count = longest_chain([n for n in numbers if n > 0])
    negative_count = longest_chain([-n for n in numbers if n < 0])
    return max(positive_count, negative_count)

