def maxAverageOfPath(matrix):
    n = len(matrix)
    dp = [0] * n
    dp[0] = matrix[0][0]
    for j in range(1, n):
        dp[j] = dp[j - 1] + matrix[0][j]
    for i in range(1, n):
        dp[0] += matrix[i][0]
        for j in range(1, n):
            dp[j] = max(dp[j], dp[j - 1]) + matrix[i][j]
    return dp[-1] / (2 * n - 1)

def maxAverageOfPath(cost):
    n = len(cost)
    i, j = 0, 0
    total = cost[0][0]
    count = 1
    while i < n - 1 or j < n - 1:
        if i == n - 1:
            j += 1
        elif j == n - 1:
            i += 1
        elif cost[i][j + 1] >= cost[i + 1][j]:
            j += 1
        else:
            i += 1
        total += cost[i][j]
        count += 1
    return total / count

def maxAverageOfPath(matrix):
    n = len(matrix)
    row = col = 0
    total = matrix[0][0]

    while row < n - 1 or col < n - 1:
        if col == n - 1 or (
            row < n - 1 and matrix[row + 1][col] > matrix[row][col + 1]
        ):
            row += 1
        else:
            col += 1
        total += matrix[row][col]

    return total / (2 * n - 1)

def maxAverageOfPath(cost):
    n = len(cost)
    if n == 0:
        return 0
    dp = [[0] * n for _ in range(n)]
    dp[0][0] = cost[0][0]
    for i in range(1, n):
        dp[i][0] = dp[i - 1][0] + cost[i][0]
    for j in range(1, n):
        dp[0][j] = dp[0][j - 1] + cost[0][j]
    for i in range(1, n):
        for j in range(1, n):
            dp[i][j] = max(dp[i - 1][j], dp[i][j - 1]) + cost[i][j]
    return dp[n - 1][n - 1] / (2 * n - 1)

