def find_first_occurrence(A, target):
    left, right = 0, len(A)
    while left < right:
        mid = (left + right) // 2
        if A[mid] < target:
            left = mid + 1
        else:
            right = mid
    return left if left < len(A) and A[left] == target else -1

def find_first_occurrence(A, x):
    if not A:
        return -1
    mid = (len(A) - 1) // 2
    if A[mid] == x:
        return mid
    low, high = 0, len(A) - 1
    result = -1
    while low <= high:
        m = (low + high) // 2
        if A[m] == x:
            result = m
            high = m - 1
        elif A[m] < x:
            low = m + 1
        else:
            high = m - 1
    return result

