def divisible_by_digits(startnum, endnum):
    result = []
    for n in range(startnum, endnum + 1):
        if n == 0:
            result.append(0)
            continue
        if n < 0:
            continue
        digits = [int(d) for d in str(n)]
        if 0 in digits:
            continue
        if all(n % d == 0 for d in digits):
            result.append(n)
    return result

