def count_divisors(n):
    if n <= 0:
        return True

    divisor_count = 1
    factor = 2
    while factor * factor <= n:
        exponent = 0
        while n % factor == 0:
            n //= factor
            exponent += 1
        divisor_count *= exponent + 1
        factor = 3 if factor == 2 else factor + 2

    if n > 1:
        divisor_count *= 2

    pair_count = (divisor_count + 1) // 2
    return pair_count % 2 == 0

