def max_sum_list(lists):
    if not lists:
        return []
    elements = [x for sub in lists for x in sub]
    if elements:
        top = max(elements)
        if elements.count(top) == 1:
            for sub in lists:
                if top in sub:
                    return sub
    return max(lists, key=sum)

def max_sum_list(lists):
    elements = [value for sublist in lists for value in sublist]
    if elements:
        greatest = max(elements)
        if elements.count(greatest) == 1:
            return next(sublist for sublist in lists if greatest in sublist)
    return max(lists, key=sum)

